import json
import itertools

def generate_permutations(items, fixed_item_to_pos):
    n = len(items)
    arr = [None] * n
    used_items = set()

    # Place fixed items
    for item, pos in fixed_item_to_pos.items():
        if pos is None or pos < 1 or pos > n:
            return  # no permutations possible
        if arr[pos - 1] is not None and arr[pos - 1] != item:
            return
        arr[pos - 1] = item
        used_items.add(item)

    remaining_items = [it for it in items if it not in used_items]
    remaining_positions = [i + 1 for i, v in enumerate(arr) if v is None]

    for perm in itertools.permutations(remaining_items):
        candidate = list(arr)
        for pos, item in zip(remaining_positions, perm):
            candidate[pos - 1] = item
        yield tuple(candidate)

def get_pos(assign, category, item):
    if category not in assign:
        return None
    try:
        return assign[category].index(item) + 1
    except ValueError:
        return None

def check_constraints(assign):
    p = lambda cat, it: get_pos(assign, cat, it)

    # 18. Alice is in the first house.
    if 'Name' in assign:
        pos_alice = p('Name', 'Alice')
        if pos_alice is not None and pos_alice != 1:
            return False

    # Derived: Carol immediately left of Eric (from 3,22,23)
    if 'Name' in assign:
        pos_carol = p('Name', 'Carol')
        pos_eric = p('Name', 'Eric')
        if pos_carol is not None and pos_eric is not None:
            if pos_carol + 1 != pos_eric:
                return False

    # 1. OnePlus 9 in second house.
    if 'PhoneModel' in assign:
        pos_op9 = p('PhoneModel', 'oneplus 9')
        if pos_op9 is not None and pos_op9 != 2:
            return False

    # 2. Xiaomi Mi 11 left of Huawei P50.
    if 'PhoneModel' in assign:
        pos_xiaomi = p('PhoneModel', 'xiaomi mi 11')
        pos_huawei = p('PhoneModel', 'huawei p50')
        if pos_xiaomi is not None and pos_huawei is not None:
            if not (pos_xiaomi < pos_huawei):
                return False

    # 3. Carol loves carnations.
    if 'Name' in assign and 'Flower' in assign:
        if p('Name', 'Carol') != p('Flower', 'carnations'):
            return False

    # 4. Purple directly left of Pall Mall.
    pos_purple = p('Color', 'purple')
    pos_pallmall = p('Cigar', 'pall mall')
    if pos_purple is not None and pos_purple == 6:
        return False
    if pos_pallmall is not None and pos_pallmall == 1:
        return False
    if pos_purple is not None and pos_pallmall is not None:
        if pos_purple + 1 != pos_pallmall:
            return False

    # 5. Green equals Blue Master.
    if 'Color' in assign and 'Cigar' in assign:
        if p('Color', 'green') != p('Cigar', 'blue master'):
            return False

    # 6. Yellow and blue are next to each other.
    if 'Color' in assign:
        pos_yellow = p('Color', 'yellow')
        pos_blue = p('Color', 'blue')
        if pos_yellow is not None and pos_blue is not None:
            if abs(pos_yellow - pos_blue) != 1:
                return False

    # 7. Eric is to the right of Samsung Galaxy S21.
    if 'Name' in assign and 'PhoneModel' in assign:
        pos_eric = p('Name', 'Eric')
        pos_s21 = p('PhoneModel', 'samsung galaxy s21')
        if pos_eric is not None and pos_s21 is not None:
            if not (pos_eric > pos_s21):
                return False

    # 8. Two houses between Carol and daffodils.
    if 'Name' in assign and 'Flower' in assign:
        pos_carol = p('Name', 'Carol')
        pos_daff = p('Flower', 'daffodils')
        if pos_carol is not None and pos_daff is not None:
            if abs(pos_carol - pos_daff) != 3:
                return False

    # 9. Prince smoker loves basketball.
    if 'Cigar' in assign and 'FavoriteSport' in assign:
        if p('Cigar', 'prince') != p('FavoriteSport', 'basketball'):
            return False

    # 10. Dunhill smoker loves volleyball.
    if 'Cigar' in assign and 'FavoriteSport' in assign:
        if p('Cigar', 'dunhill') != p('FavoriteSport', 'volleyball'):
            return False

    # 11. Swimming equals Google Pixel 6.
    if 'FavoriteSport' in assign and 'PhoneModel' in assign:
        if p('FavoriteSport', 'swimming') != p('PhoneModel', 'google pixel 6'):
            return False

    # 12. Huawei P50 directly left of white.
    pos_huawei = p('PhoneModel', 'huawei p50')
    pos_white = p('Color', 'white')
    if pos_huawei is not None and pos_huawei == 6:
        return False
    if pos_white is not None and pos_white == 1:
        return False
    if pos_huawei is not None and pos_white is not None:
        if pos_huawei + 1 != pos_white:
            return False

    # 13. OnePlus 9 and roses are next to each other.
    if 'PhoneModel' in assign and 'Flower' in assign:
        pos_op9 = p('PhoneModel', 'oneplus 9')
        pos_roses = p('Flower', 'roses')
        if pos_op9 is not None and pos_roses is not None:
            if abs(pos_op9 - pos_roses) != 1:
                return False
        # Partial: if roses known but not adjacent to 2 (since op9 is 2), prune
        if pos_roses is not None and pos_op9 is not None and pos_op9 == 2:
            if pos_roses not in (1, 3):
                return False

    # 14. Iris is left of Eric.
    if 'Flower' in assign and 'Name' in assign:
        pos_iris = p('Flower', 'iris')
        pos_eric = p('Name', 'Eric')
        if pos_iris is not None and pos_eric is not None:
            if not (pos_iris < pos_eric):
                return False

    # 15. Dunhill smoker is Peter.
    if 'Cigar' in assign and 'Name' in assign:
        if p('Cigar', 'dunhill') != p('Name', 'Peter'):
            return False

    # 16. Blue is Peter.
    if 'Color' in assign and 'Name' in assign:
        if p('Color', 'blue') != p('Name', 'Peter'):
            return False

    # 17. Tulips is Bob.
    if 'Flower' in assign and 'Name' in assign:
        if p('Flower', 'tulips') != p('Name', 'Bob'):
            return False

    # 19. Baseball directly left of Blue Master.
    pos_baseball = p('FavoriteSport', 'baseball')
    pos_bluemaster = p('Cigar', 'blue master')
    if pos_baseball is not None and pos_bluemaster is not None:
        if pos_baseball + 1 != pos_bluemaster:
            return False
    if pos_baseball is not None and pos_bluemaster is None:
        # If baseball is at position 6 it cannot be directly left of any
        if pos_baseball == 6:
            return False
    if pos_baseball is None and pos_bluemaster is not None:
        # If blue master is at position 1 it cannot have left neighbor
        if pos_bluemaster == 1:
            return False

    # 20. Google Pixel 6 right of blends.
    if 'PhoneModel' in assign and 'Cigar' in assign:
        if p('PhoneModel', 'google pixel 6') is not None and p('Cigar', 'blends') is not None:
            if not (p('PhoneModel', 'google pixel 6') > p('Cigar', 'blends')):
                return False

    # 21. Soccer is Carol.
    if 'FavoriteSport' in assign and 'Name' in assign:
        if p('FavoriteSport', 'soccer') != p('Name', 'Carol'):
            return False

    # 22. Carnations directly left of blends.
    pos_carn = p('Flower', 'carnations')
    pos_blends = p('Cigar', 'blends')
    if pos_carn is not None and pos_carn == 6:
        return False
    if pos_blends is not None and pos_blends == 1:
        return False
    if pos_carn is not None and pos_blends is not None:
        if pos_carn + 1 != pos_blends:
            return False

    # 23. Eric smokes blends.
    if 'Name' in assign and 'Cigar' in assign:
        if p('Name', 'Eric') != p('Cigar', 'blends'):
            return False

    # 24. Volleyball equals iPhone 13.
    if 'FavoriteSport' in assign and 'PhoneModel' in assign:
        if p('FavoriteSport', 'volleyball') != p('PhoneModel', 'iphone 13'):
            return False

    return True

def solve():
    houses = [1,2,3,4,5,6]
    names = ['Peter', 'Carol', 'Eric', 'Alice', 'Bob', 'Arnold']
    phones = ['huawei p50', 'google pixel 6', 'xiaomi mi 11', 'iphone 13', 'samsung galaxy s21', 'oneplus 9']
    cigars = ['dunhill', 'pall mall', 'blends', 'blue master', 'prince', 'yellow monster']
    flowers = ['daffodils', 'carnations', 'roses', 'tulips', 'lilies', 'iris']
    colors = ['yellow', 'red', 'green', 'blue', 'white', 'purple']
    sports = ['soccer', 'tennis', 'basketball', 'volleyball', 'swimming', 'baseball']

    categories_order = ['Name', 'Cigar', 'PhoneModel', 'Flower', 'Color', 'FavoriteSport']
    items_by_category = {
        'Name': names,
        'PhoneModel': phones,
        'Cigar': cigars,
        'Flower': flowers,
        'Color': colors,
        'FavoriteSport': sports,
    }

    solution = {}

    def backtrack(idx, assign):
        nonlocal solution
        if idx == len(categories_order):
            # All assigned
            if check_constraints(assign):
                solution = assign.copy()
                return True
            return False

        category = categories_order[idx]

        # Build fixed mapping for this category based on current assignment
        fixed = {}

        if category == 'Name':
            fixed['Alice'] = 1

        elif category == 'Cigar':
            pos_peter = get_pos(assign, 'Name', 'Peter')
            pos_eric = get_pos(assign, 'Name', 'Eric')
            # Must be known since Name comes first
            fixed['dunhill'] = pos_peter
            fixed['blends'] = pos_eric

        elif category == 'PhoneModel':
            fixed['oneplus 9'] = 2
            pos_peter = get_pos(assign, 'Name', 'Peter')
            fixed['iphone 13'] = pos_peter  # from 10+15+24

        elif category == 'Flower':
            pos_carol = get_pos(assign, 'Name', 'Carol')
            pos_bob = get_pos(assign, 'Name', 'Bob')
            fixed['carnations'] = pos_carol
            fixed['tulips'] = pos_bob

        elif category == 'Color':
            pos_peter = get_pos(assign, 'Name', 'Peter')
            fixed['blue'] = pos_peter
            # green equals blue master
            pos_bluemaster = get_pos(assign, 'Cigar', 'blue master')
            if pos_bluemaster is not None:
                fixed['green'] = pos_bluemaster
            # white is right of Huawei
            pos_huawei = get_pos(assign, 'PhoneModel', 'huawei p50')
            if pos_huawei is not None:
                # if invalid, no permutations
                if pos_huawei == 6:
                    return False
                fixed['white'] = pos_huawei + 1
            # purple to left of pall mall
            pos_pallmall = get_pos(assign, 'Cigar', 'pall mall')
            if pos_pallmall is not None:
                if pos_pallmall == 1:
                    return False
                fixed['purple'] = pos_pallmall - 1

        elif category == 'FavoriteSport':
            pos_peter = get_pos(assign, 'Name', 'Peter')
            pos_carol = get_pos(assign, 'Name', 'Carol')
            fixed['volleyball'] = pos_peter  # from 10+15
            fixed['soccer'] = pos_carol     # from 21
            # basketball equals prince smoker
            pos_prince = get_pos(assign, 'Cigar', 'prince')
            if pos_prince is not None:
                fixed['basketball'] = pos_prince
            # swimming equals google pixel 6
            pos_pix = get_pos(assign, 'PhoneModel', 'google pixel 6')
            if pos_pix is not None:
                fixed['swimming'] = pos_pix

        # Generate permutations for this category with fixed positions
        for perm in generate_permutations(items_by_category[category], fixed):
            assign[category] = perm
            if check_constraints(assign):
                if backtrack(idx + 1, assign):
                    return True
            del assign[category]
        return False

    backtrack(0, {})

    # Prepare JSON output
    header = ["House", "Name", "PhoneModel", "Cigar", "Flower", "Color", "FavoriteSport"]
    rows = []
    for i in range(6):
        row = [
            str(i + 1),
            solution['Name'][i],
            solution['PhoneModel'][i],
            solution['Cigar'][i],
            solution['Flower'][i],
            solution['Color'][i],
            solution['FavoriteSport'][i],
        ]
        rows.append(row)

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output))

if __name__ == "__main__":
    solve()
